const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ENV_FILE_PATH = path.join(__dirname, '.env.test');
const LOG_FILE_PATH = path.join(__dirname, 'rotation-log.md');

function getSha256Hash(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function populateRotationLog() {
  if (!fs.existsSync(ENV_FILE_PATH)) {
    console.error(`Error: Environment file not found at ${ENV_FILE_PATH}`);
    return;
  }
  if (!fs.existsSync(LOG_FILE_PATH)) {
    console.error(`Error: Log template not found at ${LOG_FILE_PATH}`);
    return;
  }

  // 1. Read and parse the environment file
  const envContent = fs.readFileSync(ENV_FILE_PATH, 'utf-8');
  const envLines = envContent.split(/\r?\n/);
  const hashes = {};

  envLines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) return;

    const key = trimmed.substring(0, eqIndex).trim();
    const value = trimmed.substring(eqIndex + 1).trim();

    hashes[key] = getSha256Hash(value);
  });

  // 2. Read and update the rotation log template
  let logContent = fs.readFileSync(LOG_FILE_PATH, 'utf-8');

  Object.keys(hashes).forEach(key => {
    const placeholderPattern = new RegExp(`\\|\\s*${key}\\s*\\|\\s*\`\\[PENDING_HASH\\]\`\\s*\\|`);
    const replacement = `| ${key} | \`${hashes[key]}\` |`;
    logContent = logContent.replace(placeholderPattern, replacement);
  });

  fs.writeFileSync(LOG_FILE_PATH, logContent, 'utf-8');
  console.log('Successfully populated rotation-log.md with secure SHA-256 hashes!');
}

populateRotationLog();
```

