```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");

async function loadProductionSecrets() {
  const secretName = "production/app/secrets";
  const client = new SecretsManagerClient({ region: "us-east-1" });

  try {
    const response = await client.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    if (response.SecretString) {
      const secrets = JSON.parse(response.SecretString);

      // Inject secrets into process.env or a configuration object
      process.env.DATABASE_URL = secrets.DATABASE_URL;
      process.env.THIRD_PARTY_API_KEY = secrets.THIRD_PARTY_API_KEY;

      console.log("Secrets loaded successfully from Secrets Manager.");
    }
  } catch (error) {
    console.error("Error retrieving secrets from Secrets Manager:", error);
    throw error;
  }
}

